class IntroView extends ConsumerStatefulWidget {
  const IntroView({super.key});

  static const String routeName = "/introView";

  @override
  ConsumerState<IntroView> createState() => _IntroViewState();
}

class _IntroViewState extends ConsumerState<IntroView> {
  late final bool isDesktop;

  /// The terms and privacy policy, accepted once in [ConsentDialog] on the
  /// first start: app stores ask for an active choice, not "by using the
  /// app, you agree". This screen only shows before the app is set up, so
  /// existing users are never asked.
  bool get _canStart =>
      Prefs.instance.termsAccepted || PrivacyAndTOSText.links().isEmpty;

  /// Holds the screen until the terms are accepted: the dialog can't be
  /// dismissed, and comes back if anything else closes it.
  Future<void> _askConsent() async {
    while (mounted && !_canStart) {
      await showDialog<void>(
        context: context,
        barrierDismissible: false,
        builder: (_) => ConsentDialog(isDesktop: isDesktop),
      );
    }
    if (mounted) setState(() {});
  }

  @override
  void initState() {
    isDesktop = Util.isDesktop;
    super.initState();
    WidgetsBinding.instance.addPostFrameCallback((_) => _askConsent());
  }

  @override
  Widget build(BuildContext context) {
    return Background(
      child: AppScaffold(
        backgroundColor: Theme.of(context).extension<StackColors>()!.background,
        maxBodyWidth: ScreenFit.panesOrColumn(context),
        body: SafeArea(
          child: Center(
            child: ScreenFit.sideBySide(context)
                ? Padding(
                    padding: const EdgeInsets.all(16),
                    child: SplitPane(
                      start: Image.asset(
                        Assets.persona.welcome,
                        width: 266,
                        height: min(
                          266,
                          MediaQuery.sizeOf(context).height - 64,
                        ),
                        fit: BoxFit.contain,
                      ),
                      end: Column(
                        mainAxisSize: MainAxisSize.min,
                        crossAxisAlignment: CrossAxisAlignment.stretch,
                        children: [
                          AppNameText(isDesktop: isDesktop),
                          const SizedBox(height: 8),
                          IntroAboutText(isDesktop: isDesktop),
                          const SizedBox(height: 24),
                          GetStartedButton(
                            isDesktop: isDesktop,
                            enabled: _canStart,
                          ),
                        ],
                      ),
                    ),
                  )
                : !isDesktop
                ? LayoutBuilder(
                    // Scrolls when the screen is too short for it: a tablet
                    // in landscape, a split screen window.
                    builder: (context, constraints) => SingleChildScrollView(
                      child: ConstrainedBox(
                        constraints: BoxConstraints(
                          minHeight: constraints.maxHeight,
                        ),
                        child: IntrinsicHeight(
                          child: Column(
                            crossAxisAlignment: CrossAxisAlignment.center,
                            children: [
                              const Spacer(flex: 2),
                              Padding(
                                padding: const EdgeInsets.symmetric(
                                  horizontal: 16,
                                ),
                                child: Image.asset(
                                  Assets.persona.welcome,
                                  width: 266,
                                  height: 266,
                                  fit: BoxFit.contain,
                                ),
                              ),
                              const Spacer(flex: 1),
                              AppNameText(isDesktop: isDesktop),
                              const SizedBox(height: 8),
                              Padding(
                                padding: const EdgeInsets.symmetric(
                                  horizontal: 48,
                                ),
                                child: IntroAboutText(isDesktop: isDesktop),
                              ),
                              const Spacer(flex: 4),
                              Padding(
                                padding: const EdgeInsets.symmetric(
                                  horizontal: 16,
                                  vertical: 16,
                                ),
                                child: Row(
                                  children: [
                                    Expanded(
                                      child: GetStartedButton(
                                        isDesktop: isDesktop,
                                        enabled: _canStart,
                                      ),
                                    ),
                                  ],
                                ),
                              ),
                            ],
                          ),
                        ),
                      ),
                    ),
                  )
                : SingleChildScrollView(
                    primary: false,
                    child: SizedBox(
                      width: 350,
                      height: 620,
                      child: Column(
                        children: [
                          const Spacer(flex: 2),
                          Image.asset(
                            Assets.persona.welcome,
                            width: 200,
                            height: 200,
                            fit: BoxFit.contain,
                          ),
                          const Spacer(flex: 42),
