class IntroAboutText extends StatelessWidget {
  const IntroAboutText({super.key, required this.isDesktop});

  final bool isDesktop;

  // Lines break between the short sentences ("Your privacy. Your keys." /
  // "Your PIVX."), never inside one.
  static String _breakBetweenSentences(String text) => text
      .split(". ")
      .map((sentence) => sentence.replaceAll(" ", "\u00a0"))
      .join(". ");

  @override
  Widget build(BuildContext context) {
    return Text(
      _breakBetweenSentences(AppConfig.shortDescriptionText),
      textAlign: TextAlign.center,
      style: !isDesktop
          ? STextStyles.subtitle(context)
          : STextStyles.subtitle(context).copyWith(fontSize: 24),
    );
  }
}

/// "By using the app you agree to the Terms of service and Privacy
/// policy", with whichever of the two links the app config sets (nothing
/// when neither).
class PrivacyAndTOSText extends StatelessWidget {
  const PrivacyAndTOSText({
    super.key,
    required this.isDesktop,
    this.fontSize,
    this.textColor,
  });

  final bool isDesktop;
  final double? fontSize;
  final Color? textColor;

  /// The terms and privacy policy links (title, url) the app config sets.
  static List<(String, String)> links() => [
    if (AppConfig.termsUrl.isNotEmpty)
      (l10n.introTermsLink, AppConfig.termsUrl),
    if (AppConfig.privacyUrl.isNotEmpty)
      (l10n.introPrivacyLink, AppConfig.privacyUrl),
  ];

  @override
  Widget build(BuildContext context) {
    final size = fontSize ?? (isDesktop ? 18.0 : 12.0);
    final links = PrivacyAndTOSText.links();
    if (links.isEmpty) return const SizedBox.shrink();
    final textStyle = STextStyles.label(context)
        .copyWith(fontSize: size, color: textColor);
    // The sentence with \u0000 and \u0001 where the links go.
    final sentence = links.length == 1
        ? l10n.introAgreeOne(AppConfig.appName, "\u0000")
        : l10n.introAgreeTwo(AppConfig.appName, "\u0000", "\u0001");
    return RichText(
      textAlign: TextAlign.center,
      text: TextSpan(
        style: textStyle,
        children: linkedSpans(context, sentence, links, size),
      ),
    );
  }

  /// [sentence] with each \u0000 / \u0001 replaced by that link of [links].
  static List<InlineSpan> linkedSpans(
    BuildContext context,
    String sentence,
    List<(String, String)> links,
    double size,
  ) {
    final children = <InlineSpan>[];
    var at = 0;
    for (final m in RegExp("[\u0000\u0001]").allMatches(sentence)) {
      final link = links[sentence.codeUnitAt(m.start)];
      children.addAll([
        TextSpan(text: sentence.substring(at, m.start)),
        TextSpan(
          text: link.$1,
          style: STextStyles.richLink(context).copyWith(fontSize: size),
          recognizer: TapGestureRecognizer()
            ..onTap = () => launchUrl(
              Uri.parse(link.$2),
              mode: LaunchMode.externalApplication,
            ),
        ),
      ]);
      at = m.end;
    }
    children.add(TextSpan(text: sentence.substring(at)));
    return children;
  }
}

/// The first-start dialog: the terms and privacy policy links, which open
/// in the browser, then "I have read and agree" and Continue. It can't be
/// dismissed (no barrier tap, back or Escape). The box unlocks once every
/// link was opened, and Continue once the box is ticked.
class ConsentDialog extends StatefulWidget {
  const ConsentDialog({super.key, required this.isDesktop});

  final bool isDesktop;

  @override
  State<ConsentDialog> createState() => _ConsentDialogState();
}

class _ConsentDialogState extends State<ConsentDialog> {
  final _opened = {...Prefs.instance.termsOpened};
  // Links no browser could open: their addresses are shown to copy.
  final _failed = <String>{};
  bool _agreed = false;
  bool _saving = false;

  Future<void> _open(String url) async {
    // Stored first: the phone may close the app while the browser is open.
    await Prefs.instance.markTermsOpened(url);
    var ok = false;
    try {
      ok = await launchUrl(
        Uri.parse(url),
        mode: LaunchMode.externalApplication,
      );
    } catch (_) {}
    if (!mounted) return;
    setState(() {
      if (!ok) _failed.add(url);
      _opened.add(url);
    });
  }

  Future<void> _continue() async {
    setState(() => _saving = true);
    await Prefs.instance.acceptTerms();
    if (mounted) Navigator.of(context).pop();
  }

  @override
  Widget build(BuildContext context) {
    final colors = Theme.of(context).extension<StackColors>()!;
    final links = PrivacyAndTOSText.links();
    final desktop = widget.isDesktop;
    final size = desktop ? 18.0 : 14.0;
    final canTick = links.every((l) => _opened.contains(l.$2));
    final canContinue = _agreed && canTick && !_saving;
    final body = (desktop
            ? STextStyles.desktopTextSmall(context)
            : STextStyles.smallMed14(context))
        .copyWith(fontSize: size);
    final agree = links.length == 1
        ? l10n.introConsentOne(links.first.$1)
        : l10n.introConsentTwo(links.first.$1, links.last.$1);

    return PopScope(
      canPop: false,
      child: StackDialogBase(
        child: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            Text(
              l10n.introConsentTitle,
              style: desktop
                  ? STextStyles.desktopH3(context)
                  : STextStyles.pageTitleH2(context),
            ),
            const SizedBox(height: 12),
            Text(l10n.introConsentRead, style: body),
            const SizedBox(height: 8),
            for (final link in links) ...[
              InkWell(
                borderRadius: BorderRadius.circular(8),
                onTap: () => _open(link.$2),
                child: Padding(
                  padding: const EdgeInsets.symmetric(vertical: 10),
                  child: Row(
                    children: [
                      Icon(
                        _opened.contains(link.$2)
                            ? Icons.check_circle
                            : Icons.open_in_new,
                        size: size + 4,
                        color: _opened.contains(link.$2)
                            ? colors.accentColorGreen
                            : colors.accentColorBlue,
                      ),
                      const SizedBox(width: 10),
                      Flexible(
                        child: Text(
                          link.$1,
                          style: STextStyles.richLink(
                            context,
                          ).copyWith(fontSize: size),
                        ),
                      ),
                    ],
                  ),
                ),
              ),
              if (_failed.contains(link.$2))
                Padding(
                  padding: const EdgeInsetsDirectional.only(
                    start: 32,
                    bottom: 6,
                  ),
                  child: SelectableText(link.$2, style: body),
                ),
            ],
            const SizedBox(height: 8),
            GestureDetector(
              behavior: HitTestBehavior.opaque,
              onTap: canTick ? () => setState(() => _agreed = !_agreed) : null,
              child: Row(
                children: [
                  Checkbox(
                    value: _agreed,
                    activeColor: colors.checkboxBGChecked,
                    checkColor: colors.checkboxIconChecked,
                    side: BorderSide(
                      color: canTick
                          ? colors.checkboxBorderEmpty
                          : colors.checkboxBorderEmpty.withValues(alpha: 0.4),
                      width: 2,
                    ),
                    semanticLabel: agree,
                    onChanged: canTick
                        ? (ticked) => setState(() => _agreed = ticked ?? false)
                        : null,
                  ),
                  Flexible(
                    child: Text(
                      agree,
                      style: canTick
                          ? body
                          : body.copyWith(color: colors.textSubtitle2),
                    ),
                  ),
                ],
              ),
            ),
            if (!canTick)
              Padding(
                padding: const EdgeInsetsDirectional.only(start: 12, top: 4),
                child: Text(
                  l10n.introConsentOpenFirst,
                  style: desktop
                      ? STextStyles.desktopTextExtraExtraSmall(context)
                      : STextStyles.itemSubtitle12(context),
                ),
              ),
            const SizedBox(height: 20),
            PrimaryButton(
              label: l10n.commonContinue,
              enabled: canContinue,
              buttonHeight: desktop ? ButtonHeight.l : ButtonHeight.xl,
              onPressed: canContinue ? _continue : null,
            ),
          ],
        ),
      ),
    );
  }
}

class GetStartedButton extends StatelessWidget {
  const GetStartedButton({
    super.key,
    required this.isDesktop,
    this.enabled = true,
  });

  final bool isDesktop;
  final bool enabled;

  @override
  Widget build(BuildContext context) {
    return !isDesktop
        ? TextButton(
            style: enabled
                ? Theme.of(context)
                      .extension<StackColors>()!
                      .getPrimaryEnabledButtonStyle(context)
                : Theme.of(context)
                      .extension<StackColors>()!
                      .getPrimaryDisabledButtonStyle(context),
            onPressed: !enabled
                ? null
                : () {
                    Prefs.instance.externalCalls = true;
                    Navigator.of(
                      context,
                    ).pushNamed(StackPrivacyCalls.routeName, arguments: false);
                  },
            child: Text(
              l10n.introGetStarted,
              style: STextStyles.button(context),
            ),
          )
        : SizedBox(
            width: double.infinity,
            height: 70,
            child: TextButton(
              style: enabled
                  ? Theme.of(context)
                        .extension<StackColors>()!
                        .getPrimaryEnabledButtonStyle(context)
                  : Theme.of(context)
                        .extension<StackColors>()!
                        .getPrimaryDisabledButtonStyle(context),
              onPressed: !enabled
                  ? null
                  : () {
                      // As on mobile: Easy Crypto until chosen otherwise.
                      Prefs.instance.externalCalls = true;
                      Navigator.of(context).pushNamed(
                        StackPrivacyCalls.routeName,
                        arguments: false,
                      );
                    },
              child: Text(
                l10n.introCreateNew(AppConfig.prefix),
                style: STextStyles.button(context).copyWith(fontSize: 20),
              ),
            ),
          );
  }
}
